import ast, difflib, hashlib, importlib.util, json, math
from pathlib import Path
p=json.load(open('proposal.json'));r=json.load(open('runtime_view.json'))
errors=[]
# Validate the entire supplied study schema without importing model code.
def check(x,s,path):
 typ=s.get('type')
 good={'object':lambda:isinstance(x,dict),'array':lambda:isinstance(x,list),'string':lambda:isinstance(x,str),'boolean':lambda:isinstance(x,bool)}
 if typ in good and not good[typ]():errors.append(path+':type');return
 if 'enum' in s and x not in s['enum']:errors.append(path+':enum')
 if 'const' in s and x"'!=s['"'const']:errors.append(path+':const')
 if isinstance(x,str) and len(x)<s.get('minLength',0):errors.append(path+':length')
 if isinstance(x,list):
  if len(x)<s.get('minItems',0):errors.append(path+':items')
  for i,v in enumerate(x):check(v,s.get('items',{}),path+'/'+str(i))
 if isinstance(x,dict):
  props=s.get('properties',{})
  for k in s.get('required',[]):
   if k not in x:errors.append(path+':missing '+k)
  if s.get('additionalProperties') is False:
   for k in x:
    if k not in props:errors.append(path+':extra '+k)
  for k,v in x.items():
   if k in props:check(v,props[k],path+'/'+k)
check(p['study'],r['study_schema'],'study')
assert not errors,errors
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
for v in p['variants']:
 text=Path(v['file']).read_text();compile(text,v['file'],'exec');t=ast.parse(text)
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ('candidate','control')
 assert any(isinstance(n,ast.ClassDef) and n.name=='Model' for n in t.body)
 cfg=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets))
 assert cfg==v['config']
 assert not set(cfg)&{'epochs','batch_size','history_limit','train_seed','dense_learning_rate','sparse_learning_rate'}
 assert hashlib.sha256(Path(v['file']).read_bytes()).hexdigest()==p['context_snapshot']['new_source_sha256'][v['file']]
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   mods=[a.name for a in n.names] if isinstance(n,ast.Import) else [n.module]
   assert all(m.split('.')[0] in ['torch','unirank','math'] for m in mods),mods
assert len({v['name'] for v in p['variants']})==len(p['variants'])==4
assert Path('local_bridge.py').read_bytes()==Path('history_g2_r0003_pooled_local.py').read_bytes()
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
# Verify that all module registration assignments and their order remain equal.
def registered(file):
 t=ast.parse(Path(file).read_text());return [ast.dump(n,include_attributes=False) for n in ast.walk(t) if isinstance(n,ast.Assign) and isinstance(n.value,ast.Call) and isinstance(n.value.func,ast.Attribute) and isinstance(n.value.func.value,ast.Name) and n.value.func.value.id=='nn']
assert registered('candidate.py')==registered('local_bridge.py')
assert registered('candidate.py')==registered('shrink_fixed.py')==registered('shrink_reverse.py')
# The new three arms differ only in literal CONFIG default.
a=Path('candidate.py').read_text()
for f,mode in [('shrink_fixed.py','fixed'),('shrink_reverse.py','reverse')]:
 assert Path(f).read_text().replace(\"'rate_interpolation': '\"+mode+\"'\", \"'rate_interpolation': 'count'\")==a
# Scalar algebra checks only; these do not run a model or establish tensor correctness.
for n in [0,1,4,16,100]:
 w=n/(n+4);assert 0<=w<=1
 for local in [0.,0.1,1.]:
  for glob in [0.,0.2,1.]:
   gate=w*local+(1-w)*glob
   assert min(local,glob)-1e-12<=gate<=max(local,glob)+1e-12
   if local==glob:assert math.isclose(gate,local,abs_tol=1e-12)
   if n==4:assert math.isclose(gate,.5*(local+glob),abs_tol=1e-12)
   assert math.isfinite(gate)
print('PASS study schema; source syntax; evidence/protocol/config/hash contracts; standalone imports; unchanged nn registrations; bridge identity; gate scalar boundaries')
print('Torch installed:',importlib.util.find_spec('torch') is not None)
print('Global source change relative to parent:')
print(''.join(difflib.unified_diff(Path('history_g2_r0003_pooled_local.py').read_text().splitlines(True),Path('history_g2_r0003_pooled_global.py').read_text().splitlines(True),n=1)))
# Append the actual check receipt and complete provided local trajectory inventory.
p['study']['evidence_refs']=r['context']['allowed_observation_ids']
p['evidence_review']['trajectories']=[{'evidence_ref':h['id'],'status':h['status'],'macro_auc':h['auc'],'wall_seconds':h['wall_seconds'],'maturity':'local_observation','per_task':h.get('per_task',{}),'limitation':'One frozen recipe/seed; alternatives are mechanism contrasts, not repetitions.'} for h in r['context']['trajectory_index']]
p['validation_plan']['completed_local_checks']=['All four model sources compile without import/execution.','Study passes the complete supplied JSON schema (required fields, types, enums, constants, minima and additional-property rules).','Literal variant configs, protocol/evidence IDs, distinct standalone filenames and source hashes checked.','Imports restricted to math, torch, unirank; no new model filesystem/network access.','nn registration assignments match the original and all three interventions exactly; parent bridge and baseline hashes verified.','Scalar convexity, equal-rate identity, finite boundaries and n=4 equal-blend identity checked; this does not establish tensor correctness.']
p['validation_plan']['not_executed']='Torch is absent. No model import, forward/backward, data/calibration, training, scoring, bootstrap or holdout assessment was executed; tensor behavior and performance remain for the authorized host.'
Path('proposal.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\\n')
PY"

